16	std::vector<lbcrypto::NativeInteger> OrderedModuli(const lbcrypto::DCRTPoly& polynomial) {
17	    std::vector<lbcrypto::NativeInteger> moduli;
18	    moduli.reserve(polynomial.GetAllElements().size());
19	    for (const auto& tower : polynomial.GetAllElements()) {
20	        moduli.push_back(tower.GetModulus());
21	    }
22	    return moduli;
23	}
