38	bool HasCompleteOrderedBasis(
39	    const lbcrypto::DCRTPoly& polynomial,
40	    const std::shared_ptr<lbcrypto::ILDCRTParams<lbcrypto::BigInteger>>& expectedBasis) {
41	    const auto& actualBasis = polynomial.GetParams();
42	    if (!actualBasis || !expectedBasis || !(*actualBasis == *expectedBasis)) {
43	        return false;
44	    }
45	
46	    const auto& actualTowers = polynomial.GetAllElements();
47	    const auto& expectedTowers = expectedBasis->GetParams();
48	    if (actualTowers.size() != expectedTowers.size()) {
49	        return false;
50	    }
51	    for (std::size_t index = 0; index < actualTowers.size(); ++index) {
52	        const auto& actualTowerBasis = actualTowers[index].GetParams();
53	        if (!actualTowerBasis || !expectedTowers[index] ||
54	            !(*actualTowerBasis == *expectedTowers[index])) {
55	            return false;
56	        }
57	    }
58	    return true;
59	}
