61	bool IsInEvaluationFormat(const lbcrypto::DCRTPoly& polynomial) {
62	    if (polynomial.GetFormat() != Format::EVALUATION) {
63	        return false;
64	    }
65	    for (const auto& tower : polynomial.GetAllElements()) {
66	        if (tower.GetFormat() != Format::EVALUATION) {
67	            return false;
68	        }
69	    }
70	    return true;
71	}
