343	void DoubleCKKS::ValidateDcpInput(const ReadOnlyCiphertext& ciphertext) const {
344	    if (!ciphertext) {
345	        Invalid("DCP input is null");
346	    }
347	    if (ciphertext->GetEncodingType() != lbcrypto::CKKS_PACKED_ENCODING) {
348	        Invalid("DCP input must use CKKS packed encoding metadata");
349	    }
350	    if (ciphertext->GetLevel() != 0) {
351	        Invalid("DCP input must be at level zero");
352	    }
353	    if (ciphertext->GetNoiseScaleDeg() != 2) {
354	        Invalid("DCP input must have noise-scale degree two");
355	    }
356	    if (!std::isfinite(ciphertext->GetScalingFactor()) ||
357	        ciphertext->GetScalingFactor() != expectedInputScalingFactor_) {
358	        Invalid("DCP input must have the exact fresh degree-two FIXEDMANUAL scaling factor");
359	    }
360	    ValidateCiphertext(ciphertext, fullModuli_, 0, 2, expectedInputScalingFactor_, ciphertext->GetKeyTag(),
361	                       ciphertext->GetSlots(), 2, "pair", "DCP input");
362	}
