364	CiphertextPair DoubleCKKS::DCP(const ReadOnlyCiphertext& ciphertext) const {
365	    ValidateDcpInput(ciphertext);
366	
367	    std::vector<lbcrypto::NativeInteger> quotientFactors;
368	    std::vector<lbcrypto::NativeInteger> divisorInverses;
369	    quotientFactors.reserve(firstPairModuli_.size());
370	    divisorInverses.reserve(firstPairModuli_.size());
371	    for (const auto& modulus : firstPairModuli_) {
372	        const auto divisorInverse = divisor_.ModInverse(modulus);
373	        divisorInverses.push_back(divisorInverse);
374	        quotientFactors.push_back(modulus - divisorInverse);
375	    }
376	
377	    std::vector<lbcrypto::DCRTPoly> highElements;
378	    std::vector<lbcrypto::DCRTPoly> lowElements;
379	    highElements.reserve(ciphertext->GetElements().size());
380	    lowElements.reserve(ciphertext->GetElements().size());
381	
382	    for (const auto& source : ciphertext->GetElements()) {
383	        auto high = source;
384	        high.DropLastElementAndScale(quotientFactors, divisorInverses);
385	
386	        auto sourcePrefix = source;
387	        sourcePrefix.DropLastElement();
388	        auto scaledHigh = high;
389	        scaledHigh *= divisor_;
390	        sourcePrefix -= scaledHigh;
391	
392	        highElements.push_back(std::move(high));
393	        lowElements.push_back(std::move(sourcePrefix));
394	    }
395	
396	    auto highCiphertext = ciphertext->Clone();
397	    highCiphertext->SetElements(std::move(highElements));
398	    highCiphertext->SetLevel(1);
399	
400	    auto lowCiphertext = ciphertext->Clone();
401	    lowCiphertext->SetElements(std::move(lowElements));
402	    lowCiphertext->SetLevel(1);
403	
404	    const double recordedScalingFactor = ciphertext->GetScalingFactor();
405	    PaperScaleDescriptor paperScale{
406	        recordedScalingFactor,
407	        divisor_,
408	        static_cast<long double>(recordedScalingFactor) /
409	            static_cast<long double>(divisor_.ConvertToInt()),
410	        static_cast<long double>(recordedScalingFactor),
411	    };
412	
413	    CiphertextPair pair(std::move(highCiphertext), std::move(lowCiphertext), context_.get(), divisor_,
414	                        firstPairModuli_, 1, paperScale, recordedScalingFactor, 2,
415	                        PairLifecycle::ReadyForFirstMult, ciphertext->GetKeyTag(), ciphertext->GetSlots(),
416	                        Format::EVALUATION, 2);
417	    ValidatePair(pair);
418	    return pair;
419	}
