421	void DoubleCKKS::ValidatePair(const CiphertextPair& pair) const {
422	    if (pair.contextIdentity_ != context_.get()) {
423	        Invalid("pair belongs to a different context");
424	    }
425	    if (pair.divisor_ != divisor_) {
426	        Invalid("pair divisor does not match the bound context");
427	    }
428	    if (pair.componentCount_ != 2 || pair.format_ != Format::EVALUATION) {
429	        Invalid("pair shape or format is invalid");
430	    }
431	    if (pair.level_ == 0 || pair.level_ >= fullModuli_.size()) {
432	        Invalid("pair level is outside the supported context basis");
433	    }
434	
435	    std::vector<lbcrypto::NativeInteger> expectedModuli(fullModuli_.begin(), fullModuli_.end() - pair.level_);
436	    if (!SameOrderedModuli(pair.orderedModuli_, expectedModuli)) {
437	        Invalid("pair ordered RNS basis does not match its level");
438	    }
439	    if (!std::isfinite(pair.recordedScalingFactor_) ||
440	        pair.recordedScalingFactor_ != expectedInputScalingFactor_) {
441	        Invalid("pair scale metadata is invalid");
442	    }
443	    const long double expectedLogicalScalingFactor =
444	        static_cast<long double>(pair.recordedScalingFactor_) /
445	        static_cast<long double>(divisor_.ConvertToInt());
446	    if (pair.paperScale_.inputRecordedScalingFactor != pair.recordedScalingFactor_ ||
447	        pair.paperScale_.divisor != divisor_ ||
448	        !std::isfinite(pair.paperScale_.approximateLogicalScalingFactor) ||
449	        pair.paperScale_.approximateLogicalScalingFactor != expectedLogicalScalingFactor) {
450	        Invalid("pair paper-scale descriptor is inconsistent");
451	    }
452	    if (pair.keyTag_.empty()) {
453	        Invalid("pair key tag is empty");
454	    }
455	
456	    ValidateCiphertext(pair.high_, pair.orderedModuli_, pair.level_, pair.noiseScaleDegree_,
457	                       pair.recordedScalingFactor_, pair.keyTag_, pair.slots_, 2, "pair", "pair high");
458	    ValidateCiphertext(pair.low_, pair.orderedModuli_, pair.level_, pair.noiseScaleDegree_,
459	                       pair.recordedScalingFactor_, pair.keyTag_, pair.slots_, 2, "pair", "pair low");
460	}
