498	void DoubleCKKS::ValidateTensorResult(const TensorCiphertextPair& pair) const {
499	    if (pair.contextIdentity_ != context_.get()) {
500	        Invalid("Tensor2 result belongs to a different context");
501	    }
502	    if (pair.divisor_ != divisor_) {
503	        Invalid("Tensor2 result divisor does not match the bound context");
504	    }
505	    if (pair.componentCount_ != 3 || pair.format_ != Format::EVALUATION) {
506	        Invalid("Tensor2 result shape or format is invalid");
507	    }
508	    if (pair.level_ != 1 || !SameOrderedModuli(pair.orderedModuli_, firstPairModuli_)) {
509	        Invalid("Tensor2 result basis or level is invalid");
510	    }
511	
512	    const double baseScalingFactor = parameters_->GetScalingFactorReal(0);
513	    const double expectedRecordedScalingFactor =
514	        expectedInputScalingFactor_ * expectedInputScalingFactor_ / baseScalingFactor;
515	    if (!std::isfinite(pair.recordedScalingFactor_) || pair.recordedScalingFactor_ <= 0.0 ||
516	        pair.recordedScalingFactor_ != expectedRecordedScalingFactor) {
517	        Invalid("Tensor2 result scale metadata is invalid");
518	    }
519	    if (pair.noiseScaleDegree_ != 3) {
520	        Invalid("Tensor2 result noise-scale degree is invalid");
521	    }
522	    if (pair.keyTag_.empty()) {
523	        Invalid("Tensor2 result key tag is empty");
524	    }
525	
526	    const long double divisor = static_cast<long double>(divisor_.ConvertToInt());
527	    const long double inputHighScale = static_cast<long double>(expectedInputScalingFactor_) / divisor;
528	    const long double expectedHighScale = inputHighScale * inputHighScale;
529	    const long double expectedRecombinedScale =
530	        static_cast<long double>(expectedInputScalingFactor_) *
531	        static_cast<long double>(expectedInputScalingFactor_) / divisor;
532	    if (!std::isfinite(pair.tensorScale_.approximateHighLogicalScalingFactor) ||
533	        !std::isfinite(pair.tensorScale_.approximateRecombinedLogicalScalingFactor) ||
534	        pair.tensorScale_.approximateHighLogicalScalingFactor != expectedHighScale ||
535	        pair.tensorScale_.approximateRecombinedLogicalScalingFactor != expectedRecombinedScale) {
536	        Invalid("Tensor2 result paper-scale descriptor is inconsistent");
537	    }
538	
539	    ValidateCiphertext(pair.high_, pair.orderedModuli_, pair.level_, pair.noiseScaleDegree_,
540	                       pair.recordedScalingFactor_, pair.keyTag_, pair.slots_, 3, "Tensor2", "Tensor2 high");
541	    ValidateCiphertext(pair.low_, pair.orderedModuli_, pair.level_, pair.noiseScaleDegree_,
542	                       pair.recordedScalingFactor_, pair.keyTag_, pair.slots_, 3, "Tensor2", "Tensor2 low");
543	}
