545	TensorCiphertextPair DoubleCKKS::Tensor2(const CiphertextPair& left, const CiphertextPair& right) const {
546	    ValidatePair(left);
547	    ValidatePair(right);
548	    ValidateTensorCompatibility(left, right);
549	
550	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> leftHigh = left.high_;
551	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> leftLow = left.low_;
552	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> rightHigh = right.high_;
553	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> rightLow = right.low_;
554	
555	    auto high3 = context_->EvalMultNoRelin(leftHigh, rightHigh);
556	    auto cross12 = context_->EvalMultNoRelin(leftHigh, rightLow);
557	    auto cross21 = context_->EvalMultNoRelin(leftLow, rightHigh);
558	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> cross12Const = cross12;
559	    lbcrypto::ConstCiphertext<lbcrypto::DCRTPoly> cross21Const = cross21;
560	    auto low3 = context_->EvalAdd(cross12Const, cross21Const);
561	
562	    const double baseScalingFactor = parameters_->GetScalingFactorReal(0);
563	    const double rawRecordedScalingFactor = left.recordedScalingFactor_ * right.recordedScalingFactor_;
564	    const double normalizedRecordedScalingFactor = rawRecordedScalingFactor / baseScalingFactor;
565	    const std::size_t rawNoiseScaleDegree = left.noiseScaleDegree_ + right.noiseScaleDegree_;
566	    const std::size_t normalizedNoiseScaleDegree = rawNoiseScaleDegree - 1;
567	
568	    if (high3->GetNoiseScaleDeg() != rawNoiseScaleDegree || low3->GetNoiseScaleDeg() != rawNoiseScaleDegree ||
569	        high3->GetScalingFactor() != rawRecordedScalingFactor || low3->GetScalingFactor() != rawRecordedScalingFactor) {
570	        Invalid("Tensor2 OpenFHE raw multiplication metadata is unexpected");
571	    }
572	
573	    high3->SetNoiseScaleDeg(normalizedNoiseScaleDegree);
574	    high3->SetScalingFactor(normalizedRecordedScalingFactor);
575	    low3->SetNoiseScaleDeg(normalizedNoiseScaleDegree);
576	    low3->SetScalingFactor(normalizedRecordedScalingFactor);
577	
578	    TensorScaleDescriptor tensorScale{
579	        left.paperScale_.approximateLogicalScalingFactor * right.paperScale_.approximateLogicalScalingFactor,
580	        static_cast<long double>(left.paperScale_.inputRecordedScalingFactor) *
581	            static_cast<long double>(right.paperScale_.inputRecordedScalingFactor) /
582	            static_cast<long double>(divisor_.ConvertToInt()),
583	    };
584	
585	    TensorCiphertextPair result(std::move(high3), std::move(low3), context_.get(), divisor_, left.orderedModuli_,
586	                                left.level_, tensorScale, normalizedRecordedScalingFactor,
587	                                normalizedNoiseScaleDegree, left.keyTag_, left.slots_, Format::EVALUATION, 3);
588	    ValidateTensorResult(result);
589	    return result;
590	}
