592	CiphertextPair DoubleCKKS::Relin2(const TensorCiphertextPair& tensor) const {
593	    ValidateTensorResult(tensor);
594	    if (tensor.GetOrderedModuli().size() < tensor.GetNoiseScaleDegree()) {
595	        Invalid("Relin2 requires at least as many active Q_l towers as the Tensor noise-scale degree");
596	    }
597	    const auto& evaluationKeys = lbcrypto::CryptoContextImpl<lbcrypto::DCRTPoly>::GetAllEvalMultKeys();
598	    const auto evaluationKey = evaluationKeys.find(tensor.GetKeyTag());
599	    if (evaluationKey == evaluationKeys.end()) {
600	        Invalid("Relin2 evaluation key is missing for the Tensor key tag");
601	    }
602	    if (evaluationKey->second.empty()) {
603	        Invalid("Relin2 evaluation-key vector is empty");
604	    }
605	    const auto& firstEvaluationKey = evaluationKey->second.front();
606	    if (!firstEvaluationKey) {
607	        Invalid("Relin2 first evaluation key is null");
608	    }
609	    if (firstEvaluationKey->GetCryptoContext().get() != context_.get()) {
610	        Invalid("Relin2 first evaluation key belongs to a different context");
611	    }
612	    if (firstEvaluationKey->GetKeyTag() != tensor.GetKeyTag()) {
613	        Invalid("Relin2 first evaluation key tag does not match the Tensor key tag");
614	    }
615	    const auto relinearizationKey =
616	        std::dynamic_pointer_cast<lbcrypto::EvalKeyRelinImpl<lbcrypto::DCRTPoly>>(firstEvaluationKey);
617	    if (!relinearizationKey) {
618	        Invalid("Relin2 first evaluation key has the wrong concrete subtype");
619	    }
620	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::BV && parameters_->GetDigitSize() == 0 &&
621	        relinearizationKey->GetAVector().size() != parameters_->GetElementParams()->GetParams().size()) {
622	        Invalid("Relin2 evaluation key BV A vector length mismatch");
623	    }
624	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::BV && parameters_->GetDigitSize() == 0 &&
625	        relinearizationKey->GetBVector().size() != parameters_->GetElementParams()->GetParams().size()) {
626	        Invalid("Relin2 evaluation key BV B vector length mismatch");
627	    }
628	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::BV) {
629	        const auto expectedBasis = parameters_->GetElementParams();
630	        for (const auto& entry : relinearizationKey->GetAVector()) {
631	            if (!HasCompleteOrderedBasis(entry, expectedBasis)) {
632	                Invalid("Relin2 evaluation key BV entry basis mismatch");
633	            }
634	        }
635	        for (const auto& entry : relinearizationKey->GetBVector()) {
636	            if (!HasCompleteOrderedBasis(entry, expectedBasis)) {
637	                Invalid("Relin2 evaluation key BV entry basis mismatch");
638	            }
639	        }
640	    }
641	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::BV && parameters_->GetDigitSize() != 0) {
642	        const auto digitSize = parameters_->GetDigitSize();
643	        std::size_t expectedVectorSize = 0;
644	        for (const auto& towerParameters : parameters_->GetElementParams()->GetParams()) {
645	            const auto towerBits = towerParameters->GetModulus().GetMSB();
646	            expectedVectorSize += static_cast<std::size_t>((towerBits + digitSize - 1) / digitSize);
647	        }
648	        if (relinearizationKey->GetAVector().size() != expectedVectorSize) {
649	            Invalid("Relin2 evaluation key BV A vector length mismatch");
650	        }
651	        if (relinearizationKey->GetBVector().size() != expectedVectorSize) {
652	            Invalid("Relin2 evaluation key BV B vector length mismatch");
653	        }
654	    }
655	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::BV) {
656	        for (const auto& entry : relinearizationKey->GetAVector()) {
657	            if (!IsInEvaluationFormat(entry)) {
658	                Invalid("Relin2 evaluation key BV entry must be in evaluation format");
659	            }
660	        }
661	        for (const auto& entry : relinearizationKey->GetBVector()) {
662	            if (!IsInEvaluationFormat(entry)) {
663	                Invalid("Relin2 evaluation key BV entry must be in evaluation format");
664	            }
665	        }
666	    }
667	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::HYBRID &&
668	        relinearizationKey->GetAVector().size() != static_cast<std::size_t>(parameters_->GetNumPartQ())) {
669	        Invalid("Relin2 evaluation key HYBRID A vector length mismatch");
670	    }
671	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::HYBRID &&
672	        relinearizationKey->GetBVector().size() != static_cast<std::size_t>(parameters_->GetNumPartQ())) {
673	        Invalid("Relin2 evaluation key HYBRID B vector length mismatch");
674	    }
675	    if (parameters_->GetKeySwitchTechnique() == lbcrypto::HYBRID) {
676	        const auto expectedBasis = parameters_->GetParamsQP();
677	        for (const auto& entry : relinearizationKey->GetAVector()) {
678	            if (!HasCompleteOrderedBasis(entry, expectedBasis)) {
679	                Invalid("Relin2 evaluation key HYBRID entry basis mismatch");
680	            }
681	        }
682	        for (const auto& entry : relinearizationKey->GetBVector()) {
683	            if (!HasCompleteOrderedBasis(entry, expectedBasis)) {
684	                Invalid("Relin2 evaluation key HYBRID entry basis mismatch");
685	            }
686	        }
687	        for (const auto& entry : relinearizationKey->GetAVector()) {
688	            if (!IsInEvaluationFormat(entry)) {
689	                Invalid("Relin2 evaluation key HYBRID entry must be in evaluation format");
690	            }
691	        }
692	        for (const auto& entry : relinearizationKey->GetBVector()) {
693	            if (!IsInEvaluationFormat(entry)) {
694	                Invalid("Relin2 evaluation key HYBRID entry must be in evaluation format");
695	            }
696	        }
697	    }
698	    throw std::logic_error("DoubleCKKS: Relin2 is not implemented");
699	}
