701	lbcrypto::Ciphertext<lbcrypto::DCRTPoly> DoubleCKKS::RCB(const CiphertextPair& pair) const {
702	    ValidatePair(pair);
703	
704	    auto result = pair.high_->Clone();
705	    auto& resultElements = result->GetElements();
706	    const auto& lowElements = pair.low_->GetElements();
707	    for (std::size_t index = 0; index < resultElements.size(); ++index) {
708	        resultElements[index] *= divisor_;
709	        resultElements[index] += lowElements[index];
710	    }
711	    return result;
712	}
