54	void CheckThrowsExactInvalidArgument(Function&& function, const std::string& expectedMessage,
55	                                     const std::string& label) {
56	    bool threw = false;
57	    try {
58	        std::invoke(std::forward<Function>(function));
59	    }
60	    catch (const std::invalid_argument& exception) {
61	        Check(exception.what() == expectedMessage,
62	              label + " reported an unexpected diagnostic: " + exception.what());
63	        threw = true;
64	    }
65	    catch (const std::exception& exception) {
66	        throw TestFailure(label + " threw the wrong exception type: " + exception.what());
67	    }
68	    Check(threw, label + " did not fail fast");
69	}
