241	KeyPolynomialSnapshot SnapshotKeyPolynomial(const DCRTPoly& polynomial, const std::string& label) {
242	    const auto& params = polynomial.GetParams();
243	    Check(params != nullptr, label + " aggregate parameters are null");
244	
245	    KeyPolynomialSnapshot snapshot{
246	        polynomial,
247	        params.get(),
248	        params->GetCyclotomicOrder(),
249	        params->GetModulus(),
250	        params->GetRootOfUnity(),
251	        polynomial.GetFormat(),
252	        {},
253	        {},
254	        {},
255	        {},
256	        {},
257	        {},
258	        {},
259	        {},
260	        {},
261	    };
262	
263	    for (const auto& towerParams : params->GetParams()) {
264	        Check(towerParams != nullptr, label + " declared tower parameters are null");
265	        snapshot.declaredTowerParamIdentities.push_back(towerParams.get());
266	        snapshot.declaredTowerCyclotomicOrders.push_back(towerParams->GetCyclotomicOrder());
267	        snapshot.declaredTowerModuli.push_back(towerParams->GetModulus());
268	        snapshot.declaredTowerRoots.push_back(towerParams->GetRootOfUnity());
269	    }
270	    for (const auto& tower : polynomial.GetAllElements()) {
271	        const auto& towerParams = tower.GetParams();
272	        Check(towerParams != nullptr, label + " actual tower parameters are null");
273	        snapshot.actualTowerParamIdentities.push_back(towerParams.get());
274	        snapshot.actualTowerCyclotomicOrders.push_back(tower.GetCyclotomicOrder());
275	        snapshot.actualTowerModuli.push_back(tower.GetModulus());
276	        snapshot.actualTowerRoots.push_back(tower.GetRootOfUnity());
277	        snapshot.actualTowerFormats.push_back(tower.GetFormat());
278	    }
279	    return snapshot;
280	}
