348	DCRTPoly CloneKeyPolynomialWithIndependentParams(const DCRTPoly& source, const std::string& label) {
349	    std::vector<DCRTPoly::PolyType> clonedTowers;
350	    clonedTowers.reserve(source.GetAllElements().size());
351	    for (std::size_t index = 0; index < source.GetAllElements().size(); ++index) {
352	        const auto& sourceTower = source.GetAllElements()[index];
353	        const auto& sourceParams = sourceTower.GetParams();
354	        Check(sourceParams != nullptr, label + " source tower parameters are null");
355	        auto clonedParams = std::make_shared<DCRTPoly::PolyType::Params>(*sourceParams);
356	        Check(clonedParams.get() != sourceParams.get() && *clonedParams == *sourceParams,
357	              label + " tower parameter clone is not independent and semantically equal");
358	        DCRTPoly::PolyType clonedTower(clonedParams, sourceTower.GetFormat());
359	        clonedTower.SetValues(sourceTower.GetValues(), sourceTower.GetFormat());
360	        Check(clonedTower.GetParams().get() != sourceParams.get() &&
361	                  *clonedTower.GetParams() == *sourceParams &&
362	                  clonedTower.GetFormat() == sourceTower.GetFormat() &&
363	                  clonedTower.GetValues() == sourceTower.GetValues(),
364	              label + " tower clone changed parameters, format, or values");
365	        clonedTowers.push_back(std::move(clonedTower));
366	    }
367	
368	    DCRTPoly clone(clonedTowers);
369	    Check(clone.GetParams().get() != source.GetParams().get() &&
370	              *clone.GetParams() == *source.GetParams() && clone == source,
371	          label + " aggregate clone is not independent and semantically equal");
372	    Check(clone.GetAllElements().size() == source.GetAllElements().size(),
373	          label + " aggregate clone changed the tower count");
374	    for (std::size_t index = 0; index < clone.GetAllElements().size(); ++index) {
375	        Check(clone.GetAllElements()[index].GetParams().get() !=
376	                  source.GetAllElements()[index].GetParams().get() &&
377	                  *clone.GetAllElements()[index].GetParams() ==
378	                  *source.GetAllElements()[index].GetParams() &&
379	                  clone.GetAllElements()[index].GetValues() ==
380	                  source.GetAllElements()[index].GetValues(),
381	              label + " returned tower clone reused parameters or changed values");
382	    }
383	    return clone;
384	}
