52	class Params {
53	    // NOTE: if any data member (below) is added/removed then update
54	    // cryptocontextparams-case.cpp and cryptocontextparams-defaults.h
55	
56	    // Scheme ID
57	    SCHEME scheme;
58	
59	    // PlaintextModulus ptModulus is used in BGV/BFV type schemes and impacts noise growth
60	    PlaintextModulus ptModulus;
61	
62	    // digitSize is used in BV Key Switching only (KeySwitchTechnique = BV) and impacts noise growth
63	    uint32_t digitSize;
64	
65	    // standardDeviation is used for Gaussian error generation
66	    float standardDeviation;
67	
68	    // Secret key distribution: GAUSSIAN, UNIFORM_TERNARY, etc.
69	    SecretKeyDist secretKeyDist;
70	
71	    // Max relinearization degree of secret key polynomial (used for lazy relinearization)
72	    uint32_t maxRelinSkDeg;
73	
74	    // key switching technique: BV or HYBRID currently
75	    // For BV we do not have extra modulus, so the security depends on ciphertext modulus Q.
76	    // For HYBRID we do have extra modulus P, so the security depends on modulus P*Q
77	    // For BV we need digitSize - digit size in digit decomposition
78	    // For HYBRID we need numLargeDigits - number of digits in digit decomposition
79	    // it is good to have alternative to numLargeDigits (possibly numPrimesInDigit?)
80	    KeySwitchTechnique ksTech;
81	
82	    // rescaling/modulus switching technique used in CKKS/BGV: FLEXIBLEAUTOEXT, FIXEDMANUL, FLEXIBLEAUTO, etc.
83	    // see https://eprint.iacr.org/2022/915 for details
84	    ScalingTechnique scalTech;
85	
86	    // max batch size of messages to be packed in encoding (number of slots)
87	    uint32_t batchSize;
88	
89	    // PRE security mode
90	    ProxyReEncryptionMode PREMode;
91	
92	    // Multiparty security mode in BFV/BGV
93	    // NOISE_FLOODING_MULTIPARTY is more secure than FIXED_NOISE_MULTIPARTY.
94	    MultipartyMode multipartyMode;
95	
96	    // Execution mode in CKKS
97	    // In EXEC_NOISE_ESTIMATION mode, we estimate the noise we need to add to the actual computation to guarantee good security.
98	    // In EXEC_EVALUATION mode, we input our noise estimate and perform the desired secure encrypted computation.
99	    ExecutionMode executionMode;
100	
101	    // Decryption noise mode in CKKS
102	    // NOISE_FLOODING_DECRYPT is more secure than FIXED_NOISE_DECRYPT, but it requires executing all computations twice.
103	    DecryptionNoiseMode decryptionNoiseMode;
