71	/**
72	 * @class CryptoContextImpl
73	 * @brief A class to simplify access to OpenFHE's PKE functionality.
74	 *
75	 * Functionality is accessed by creating an instance of CryptoContextImpl.
76	 * Various objects are "created" in the instance, but they can only be used with the context in which they were created.
77	 *
78	 * OpenFHE methods are accessed through CryptoContextImpl methods. Guards are implemented to make certain that
79	 * only valid objects that have been created in the context are used
80	 *
81	 * Contexts are created using GenCryptoContext(), and can be serialized and recovered from serialization
82	 */
83	template <typename Element>
84	class CryptoContextImpl : public Serializable {
85	    using IntType  = typename Element::Integer;
86	    using ParmType = typename Element::Params;
87	
88	    /**
89	    * @brief Checks if the cryptocontext scheme is CKKS and throws an exception if it is not.
90	    *
91	    * @param functionName the calling function name. __func__ can be used instead
92	    */
93	    inline void VerifyCKKSScheme(const std::string& functionName) const {
94	        if (!isCKKS(m_schemeId)) {
95	            std::string errMsg = std::string(functionName) +
96	                                 "() is available for the CKKS scheme only."
97	                                 " The current scheme is " +
98	                                 convertToString(m_schemeId);
99	            OPENFHE_THROW(errMsg);
100	        }
101	    }
102	
103	    /**
104	    * @brief VerifyCKKSRealDataType Checks if the CKKS data type is real and throws an exception if it is not.
105	    *
106	    * @param functionName the calling function name. __func__ can be used instead
107	    */
108	    inline void VerifyCKKSRealDataType(const std::string& functionName) const {
109	        if (GetCKKSDataType() != REAL) {
110	            std::string errMsg =
111	                "Function " + std::string(functionName) + " is available for the real CKKS data types only.";
112	            OPENFHE_THROW(errMsg);
113	        }
114	    }
115	
116	    void SetKSTechniqueInScheme();
117	
118	    const CryptoContext<Element> GetContextForPointer(const CryptoContextImpl<Element>* cc) const {
119	        const auto& contexts = CryptoContextFactory<Element>::GetAllContexts();
120	        for (const auto& ctx : contexts) {
121	            if (cc == ctx.get())
122	                return ctx;
123	        }
124	        OPENFHE_THROW("Cannot find context for the given pointer to CryptoContextImpl");
125	    }
126	
127	    /**
128	    * @brief Constructs CoefPackedEncoding or PackedEncoding in this context
129	    *
130	    * @param encoding encoding type
131	    * @param value the value to encode
132	    * @param depth the multiplicative depth to encode the plaintext at
133	    * @param level the level to encode the plaintext at
134	    * @return new plaintext
135	    */
136	    Plaintext MakePlaintext(const PlaintextEncodings encoding, const std::vector<int64_t>& value, size_t depth,
137	                            uint32_t level) const {
138	        const auto cryptoParams = std::dynamic_pointer_cast<CryptoParametersRNS>(GetCryptoParameters());
139	
140	        if (level > 0) {
141	            size_t numModuli = cryptoParams->GetElementParams()->GetParams().size();
142	            if (!isBFVRNS(m_schemeId)) {
143	                // we throw an exception if level >= numModuli. However, we use multiplicativeDepth in the error message,
144	                // so the user can understand the error more easily.
145	                if (level >= numModuli) {
146	                    uint32_t multiplicativeDepth =
147	                        (cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT) ? (numModuli - 2) : (numModuli - 1);
148	                    std::string errorMsg{"The level value should be less than or equal to "};
149	                    errorMsg +=
150	                        ((cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT) ? "(multiplicativeDepth + 1)." :
151	                                                                                    "multiplicativeDepth.");
152	                    errorMsg += " Currently: level is [" + std::to_string(level) + "] and multiplicativeDepth is [" +
153	                                std::to_string(multiplicativeDepth) + "]";
154	                    OPENFHE_THROW(errorMsg);
155	                }
156	            }
157	            else {
158	                if ((cryptoParams->GetMultiplicationTechnique() == BEHZ) ||
159	                    (cryptoParams->GetMultiplicationTechnique() == HPS)) {
160	                    OPENFHE_THROW(
161	                        "BFV: Encoding at level > 0 is not currently supported for BEHZ or HPS. Use one of the HPSPOVERQ* methods instead.");
162	                }
163	
164	                if ((cryptoParams->GetEncryptionTechnique() == EXTENDED)) {
165	                    OPENFHE_THROW(
166	                        "BFV: Encoding at level > 0 is not currently supported for the EXTENDED encryption method. Use the STANDARD encryption method instead.");
167	                }
168	                if (level >= numModuli) {
169	                    std::string errorMsg =
170	                        "The level value should be less the current number of RNS limbs in the cryptocontext.";
171	                    errorMsg += " Currently: level is [" + std::to_string(level) + "] and number of RNS limbs is [" +
172	                                std::to_string(numModuli) + "]";
173	                    OPENFHE_THROW(errorMsg);
174	                }
175	            }
176	        }
177	
178	        // uses a parameter set with a reduced number of RNS limbs corresponding to the level
179	        std::shared_ptr<ILDCRTParams<DCRTPoly::Integer>> elemParamsPtr;
180	        if (level != 0) {
181	            ILDCRTParams<DCRTPoly::Integer> elemParams = *(cryptoParams->GetElementParams());
182	            for (uint32_t i = 0; i < level; i++) {
183	                elemParams.PopLastParam();
184	            }
185	            elemParamsPtr = std::make_shared<ILDCRTParams<DCRTPoly::Integer>>(elemParams);
186	        }
187	        else {
188	            elemParamsPtr = cryptoParams->GetElementParams();
189	        }
190	
191	        NativeInteger scf{1};
192	        bool setNoiseScaleDeg = false;
193	        auto scaleTech        = cryptoParams->GetScalingTechnique();
194	        if (isBGVRNS(m_schemeId) && (scaleTech == FLEXIBLEAUTO || scaleTech == FLEXIBLEAUTOEXT)) {
195	            if (scaleTech == FLEXIBLEAUTOEXT && level == 0) {
196	                scf              = cryptoParams->GetScalingFactorIntBig(level);
197	                depth            = 1;
198	                setNoiseScaleDeg = true;
199	            }
200	            else
201	                scf = cryptoParams->GetScalingFactorInt(level);
202	        }
203	
204	        Plaintext p = PlaintextFactory::MakePlaintext(value, encoding, elemParamsPtr, this->GetEncodingParams(),
205	                                                      getSchemeId(), depth, level, scf);
206	        if (setNoiseScaleDeg)
207	            p->SetNoiseScaleDeg(2);
208	
209	        return p;
210	    }
