212	    /**
213	    * @brief Constructs CoefPackedEncoding, PackedEncoding in this context
214	    *
215	    * @param encoding encoding type
216	    * @param cc the context to create a plaintext with
217	    * @param value the value to encode
218	    * @return new plaintext
219	    */
220	    template <typename Value1>
221	    static Plaintext MakePlaintext(PlaintextEncodings encoding, CryptoContext<Element> cc, const Value1& value) {
222	        return PlaintextFactory::MakePlaintext(value, encoding, cc->GetElementParams(), cc->GetEncodingParams());
223	    }
