225	    template <typename Value1, typename Value2>
226	    static Plaintext MakePlaintext(PlaintextEncodings encoding, CryptoContext<Element> cc, const Value1& value,
227	                                   const Value2& value2) {
228	        return PlaintextFactory::MakePlaintext(encoding, cc->GetElementParams(), cc->GetEncodingParams(), value,
229	                                               value2);
