239	    static std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> GetPartialEvalAutomorphismKeyMapPtr(
240	        const std::string& keyTag, const std::vector<uint32_t>& indexList);
241	
242	    // cached evalmult keys, by secret key UID
243	    static std::map<std::string, std::vector<EvalKey<Element>>> s_evalMultKeyMap;
244	    // cached evalautomorphism keys, by secret key UID
245	    static std::map<std::string, std::shared_ptr<std::map<uint32_t, EvalKey<Element>>>> s_evalAutomorphismKeyMap;
