247	protected:
248	    // crypto parameters
249	    std::shared_ptr<CryptoParametersBase<Element>> m_params{nullptr};
250	    // algorithm used; accesses all crypto methods
251	    std::shared_ptr<SchemeBase<Element>> m_scheme{nullptr};
252	
253	    SCHEME m_schemeId{SCHEME::INVALID_SCHEME};
254	
255	    uint32_t m_keyGenLevel{0};
256	
257	    /**
258	    * @brief TypeCheck makes sure that an operation between two ciphertexts is permitted
259	    *
260	    * @param a ciphertext1
261	    * @param b ciphertext2
262	    */
263	    void TypeCheck(ConstCiphertext<Element>& a, ConstCiphertext<Element>& b, CALLER_INFO_ARGS_HDR) const {
264	        if (a == nullptr || b == nullptr) {
265	            std::string errorMsg(std::string("Null Ciphertext") + CALLER_INFO);
266	            OPENFHE_THROW(errorMsg);
267	        }
268	        if (a->GetCryptoContext().get() != this) {
269	            std::string errorMsg(std::string("Ciphertext was not created in this CryptoContext") + CALLER_INFO);
270	            OPENFHE_THROW(errorMsg);
271	        }
272	        if (a->GetCryptoContext() != b->GetCryptoContext()) {
273	            std::string errorMsg(std::string("Ciphertexts were not created in the same CryptoContext") + CALLER_INFO);
274	            OPENFHE_THROW(errorMsg);
275	        }
276	        if (a->GetKeyTag() != b->GetKeyTag()) {
277	            std::string errorMsg(std::string("Ciphertexts were not encrypted with same keys") + CALLER_INFO);
278	            OPENFHE_THROW(errorMsg);
279	        }
280	        if (a->GetEncodingType() != b->GetEncodingType()) {
281	            std::stringstream ss;
282	            ss << "Ciphertext encoding types " << a->GetEncodingType();
283	            ss << " and " << b->GetEncodingType();
284	            ss << " do not match";
285	            ss << CALLER_INFO;
286	            OPENFHE_THROW(ss.str());
287	        }
288	    }
289	
290	    /**
291	    * @brief TypeCheck makes sure that an operation between a ciphertext and a plaintext is permitted
292	    *
293	    * @param a ciphertext
294	    * @param b plaintext
295	    */
296	    void TypeCheck(ConstCiphertext<Element>& a, ConstPlaintext& b, CALLER_INFO_ARGS_HDR) const {
297	        if (a == nullptr) {
298	            std::string errorMsg(std::string("Null Ciphertext") + CALLER_INFO);
299	            OPENFHE_THROW(errorMsg);
300	        }
301	        if (b == nullptr) {
302	            std::string errorMsg(std::string("Null Plaintext") + CALLER_INFO);
303	            OPENFHE_THROW(errorMsg);
304	        }
305	        if (a->GetCryptoContext().get() != this) {
306	            std::string errorMsg(std::string("Ciphertext was not created in this CryptoContext") + CALLER_INFO);
307	            OPENFHE_THROW(errorMsg);
308	        }
309	        if (a->GetEncodingType() != b->GetEncodingType()) {
310	            std::stringstream ss;
311	            ss << "Ciphertext encoding type " << a->GetEncodingType();
312	            ss << " and Plaintext encoding type " << b->GetEncodingType();
313	            ss << " do not match";
314	            ss << CALLER_INFO;
315	            OPENFHE_THROW(ss.str());
316	        }
317	    }
318	
319	    bool Mismatched(const CryptoContext<Element> a) const {
320	        return a.get() != this;
321	    }
322	
323	    template <typename T>
324	    void ValidateKey(const T& key, CALLER_INFO_ARGS_HDR) const {
325	        if (key == nullptr) {
326	            std::string errorMsg(std::string("Key is nullptr") + CALLER_INFO);
327	            OPENFHE_THROW(errorMsg);
328	        }
329	        if (Mismatched(key->GetCryptoContext())) {
330	            std::string errorMsg(std::string("Key was not generated with the same crypto context") + CALLER_INFO);
331	            OPENFHE_THROW(errorMsg);
332	        }
333	    }
