335	    void ValidateCiphertext(ConstCiphertext<Element>& ciphertext, CALLER_INFO_ARGS_HDR) const {
336	        if (ciphertext == nullptr) {
337	            std::string errorMsg(std::string("Ciphertext is nullptr") + CALLER_INFO);
338	            OPENFHE_THROW(errorMsg);
339	        }
340	        if (Mismatched(ciphertext->GetCryptoContext())) {
341	            std::string errorMsg(std::string("Ciphertext was not generated with the same crypto context") +
342	                                 CALLER_INFO);
343	            OPENFHE_THROW(errorMsg);
344	        }
345	    }
346	
347	    void ValidateSeriesPowers(std::shared_ptr<seriesPowers<Element>> powers, CALLER_INFO_ARGS_HDR) const {
348	        if (powers == nullptr) {
349	            std::string errorMsg(std::string("The object for powers is nullptr") + CALLER_INFO);
350	            OPENFHE_THROW(errorMsg);
351	        }
352	        if (powers->powersRe.size() == 0) {
353	            std::string errorMsg(std::string("The powersRe member is empty") + CALLER_INFO);
354	            OPENFHE_THROW(errorMsg);
355	        }
356	        if (Mismatched(powers->powersRe[0]->GetCryptoContext())) {
357	            std::string errorMsg(std::string("Power ciphertext was not generated with the same crypto context") +
358	                                 CALLER_INFO);
359	            OPENFHE_THROW(errorMsg);
360	        }
361	    }
