363	    virtual Plaintext MakeCKKSPackedPlaintextInternal(const std::vector<std::complex<double>>& value,
364	                                                      size_t noiseScaleDeg, uint32_t level,
365	                                                      const std::shared_ptr<ParmType> params, uint32_t slots) const {
366	        VerifyCKKSScheme(__func__);
367	        const auto cryptoParams = std::dynamic_pointer_cast<CryptoParametersRNS>(GetCryptoParameters());
368	        if (level > 0) {
369	            // validation of level: We need to compare it to multiplicativeDepth, but multiplicativeDepth is not
370	            // readily available. so, what we get is numModuli and use it for calculations
371	            size_t numModuli = cryptoParams->GetElementParams()->GetParams().size();
372	            uint32_t multiplicativeDepth =
373	                (cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT) ? (numModuli - 2) : (numModuli - 1);
374	            // we throw an exception if level >= numModuli. however, we use multiplicativeDepth in the error message,
375	            // so the user can understand the error more easily.
376	            if (level >= numModuli) {
377	                std::string errorMsg;
378	                if (cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT)
379	                    errorMsg = "The level value should be less than or equal to (multiplicativeDepth + 1).";
380	                else
381	                    errorMsg = "The level value should be less than or equal to multiplicativeDepth.";
382	
383	                errorMsg += " Currently: level is [" + std::to_string(level) + "] and multiplicativeDepth is [" +
384	                            std::to_string(multiplicativeDepth) + "]";
385	                OPENFHE_THROW(errorMsg);
386	            }
387	        }
388	
389	        double scFact = 0;
390	        if (cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT && level == 0) {
391	            scFact = cryptoParams->GetScalingFactorRealBig(level);
392	            // In FLEXIBLEAUTOEXT mode at level 0, we don't use the noiseScaleDeg in our encoding function,
393	            // so we set it to 1 to make sure it has no effect on the encoding.
394	            noiseScaleDeg = 1;
395	        }
396	        else {
397	            scFact = cryptoParams->GetScalingFactorReal(level);
398	        }
399	
400	        Plaintext p;
401	        if (params == nullptr) {
402	            std::shared_ptr<ILDCRTParams<DCRTPoly::Integer>> elemParamsPtr;
403	            if (level != 0) {
404	                ILDCRTParams<DCRTPoly::Integer> elemParams = *(cryptoParams->GetElementParams());
405	                for (uint32_t i = 0; i < level; i++) {
406	                    elemParams.PopLastParam();
407	                }
408	                elemParamsPtr = std::make_shared<ILDCRTParams<DCRTPoly::Integer>>(elemParams);
409	            }
410	            else {
411	                elemParamsPtr = cryptoParams->GetElementParams();
412	            }
413	            // Check if plaintext has got enough slots for data (value)
414	            uint32_t ringDim = elemParamsPtr->GetRingDimension();
415	            size_t valueSize = value.size();
416	            if (valueSize > ringDim / 2) {
417	                OPENFHE_THROW("The size [" + std::to_string(valueSize) +
418	                              "] of the vector with values should not be greater than ringDim/2 [" +
419	                              std::to_string(ringDim / 2) + "] if the scheme is CKKS");
420	            }
421	            // TODO (dsuponit): we should call a version of MakePlaintext instead of calling Plaintext() directly here
422	            p = Plaintext(std::make_shared<CKKSPackedEncoding>(elemParamsPtr, this->GetEncodingParams(), value,
423	                                                               noiseScaleDeg, level, scFact, slots,
424	                                                               this->GetCKKSDataType()));
425	        }
426	        else {
427	            // Check if plaintext has got enough slots for data (value)
428	            uint32_t ringDim = params->GetRingDimension();
429	            size_t valueSize = value.size();
430	            if (valueSize > ringDim / 2) {
431	                OPENFHE_THROW("The size [" + std::to_string(valueSize) +
432	                              "] of the vector with values should not be greater than ringDim/2 [" +
433	                              std::to_string(ringDim / 2) + "] if the scheme is CKKS");
434	            }
435	            // TODO (dsuponit): we should call a version of MakePlaintext instead of calling Plaintext() directly here
436	            p = Plaintext(std::make_shared<CKKSPackedEncoding>(params, this->GetEncodingParams(), value, noiseScaleDeg,
437	                                                               level, scFact, slots, this->GetCKKSDataType()));
438	        }
439	        p->Encode();
440	
441	        // In FLEXIBLEAUTOEXT mode, a fresh plaintext at level 0 always has noiseScaleDeg 2.
442	        if (cryptoParams->GetScalingTechnique() == FLEXIBLEAUTOEXT && level == 0) {
443	            p->SetNoiseScaleDeg(2);
444	        }
445	        return p;
446	    }
