570	    /**
571	    * @brief Equality comparison operator
572	    *
573	    * @param a cryptocontext object1
574	    * @param b cryptocontext object2
575	    * @return true if the implementations have identical params and scheme
576	    * @attention this is for internal use only
577	    */
578	    friend bool operator==(const CryptoContextImpl<Element>& a, const CryptoContextImpl<Element>& b) {
579	        // Identical if the parameters and the schemes are identical... the exact
580	        // same object, OR the same type and the same values
581	        if (a.m_params.get() == b.m_params.get()) {
582	            return true;
583	        }
584	        else {
585	            if (typeid(*a.m_params.get()) != typeid(*b.m_params.get())) {
586	                return false;
587	            }
588	            if (*a.m_params.get() != *b.m_params.get())
589	                return false;
590	        }
591	
592	        if (a.m_scheme.get() == b.m_scheme.get()) {
593	            return true;
594	        }
595	        else {
596	            if (typeid(*a.m_scheme.get()) != typeid(*b.m_scheme.get())) {
597	                return false;
598	            }
599	            if (*a.m_scheme.get() != *b.m_scheme.get())
600	                return false;
601	        }
602	
603	        return true;
604	    }
