631	    template <typename ST>
632	    static bool SerializeEvalMultKey(std::ostream& ser, const ST& sertype, const std::string& keyTag = "") {
633	        const auto& evalMultKeys = CryptoContextImpl<Element>::GetAllEvalMultKeys();
634	        if (keyTag.length() == 0) {
635	            Serial::Serialize(evalMultKeys, ser, sertype);
636	        }
637	        else {
638	            const auto it = evalMultKeys.find(keyTag);
639	            if (it == evalMultKeys.end())
640	                return false;  // no such keyTag
641	
642	            std::map<std::string, std::vector<EvalKey<Element>>> omap{{it->first, it->second}};
643	
644	            Serial::Serialize(omap, ser, sertype);
645	        }
646	        return true;
647	    }
