649	    /**
650	    * @brief Serializes all EvalMult keys associated with the given CryptoContext
651	    *
652	    * @param ser stream to serialize to
653	    * @param sertype type of serialization
654	    * @param cc the CryptoContext whose keys should be serialized
655	    * @return true on success
656	    */
657	    template <typename ST>
658	    static bool SerializeEvalMultKey(std::ostream& ser, const ST& sertype, const CryptoContext<Element> cc) {
659	        std::map<std::string, std::vector<EvalKey<Element>>> omap;
660	        for (const auto& [key, vec] : CryptoContextImpl<Element>::GetAllEvalMultKeys()) {
661	            if (vec[0]->GetCryptoContext() == cc) {
662	                omap[key] = vec;
663	            }
664	        }
665	
666	        if (omap.empty())
667	            return false;
668	
669	        Serial::Serialize(omap, ser, sertype);
670	        return true;
671	    }
