862	    * @param keyTag secret key tag
863	    * @param indexList array of specific indices to deserialize keys for
864	    * @return true on success
865	    */
866	    template <typename ST>
867	    static bool DeserializeEvalAutomorphismKey(std::ostream& ser, const ST& sertype, const std::string& keyTag,
868	                                               const std::vector<uint32_t>& indexList) {
869	        if (indexList.empty())
870	            OPENFHE_THROW("indexList may not be empty");
871	        if (keyTag.empty())
872	            OPENFHE_THROW("keyTag may not be empty");
873	
874	        std::map<std::string, std::shared_ptr<std::map<uint32_t, EvalKey<Element>>>> allDeserKeys;
875	        Serial::Deserialize(allDeserKeys, ser, sertype);
876	
877	        const auto& keyMapIt = allDeserKeys.find(keyTag);
878	        if (keyMapIt == allDeserKeys.end()) {
879	            OPENFHE_THROW("Deserialized automorphism keys are not generated for ID [" + keyTag + "].");
880	        }
881	
882	        // create a new map with evalkeys for the specified indices
883	        std::map<uint32_t, EvalKey<Element>> newMap;
884	        for (const uint32_t indx : indexList) {
885	            const auto& key = keyMapIt->find(indx);
886	            if (key == keyMapIt->end()) {
887	                OPENFHE_THROW("No automorphism key generated for index [" + std::to_string(indx) + "] within keyTag [" +
888	                              keyTag + "].");
889	            }
890	            newMap[indx] = key->second;
891	        }
892	
893	        CryptoContextImpl<Element>::InsertEvalAutomorphismKey(
894	            std::make_shared<std::map<uint32_t, EvalKey<Element>>>(newMap), keyTag);
895	
896	        return true;
897	    }
