68	template <typename Element>
69	void CryptoContextImpl<Element>::SetKSTechniqueInScheme() {
70	    // check if the scheme is an RNS scheme
71	    auto schemeRNSPtr = std::dynamic_pointer_cast<SchemeRNS>(m_scheme);
72	    if (schemeRNSPtr == nullptr)
73	        OPENFHE_THROW("The scheme is not RNS-based");
74	
75	    // check if the parameter object is RNS-based
76	    auto elPtr = std::dynamic_pointer_cast<const CryptoParametersRNS>(m_params);
77	    if (elPtr == nullptr)
78	        OPENFHE_THROW("The parameter object is not RNS-based");
79	
80	    schemeRNSPtr->SetKeySwitchingTechnique(elPtr->GetKeySwitchTechnique());
81	}
