86	template <typename Element>
87	void CryptoContextImpl<Element>::EvalMultKeyGen(const PrivateKey<Element>& key) {
88	    ValidateKey(key);
89	    if (CryptoContextImpl<Element>::s_evalMultKeyMap.find(key->GetKeyTag()) ==
90	        CryptoContextImpl<Element>::s_evalMultKeyMap.end()) {
91	        // the key is not found in the map, so the key has to be generated
92	        CryptoContextImpl<Element>::s_evalMultKeyMap[key->GetKeyTag()] = {GetScheme()->EvalMultKeyGen(key)};
93	    }
94	}
