98	    ValidateKey(key);
99	    if (CryptoContextImpl<Element>::s_evalMultKeyMap.find(key->GetKeyTag()) ==
100	        CryptoContextImpl<Element>::s_evalMultKeyMap.end()) {
101	        // the key is not found in the map, so the key has to be generated
102	        CryptoContextImpl<Element>::s_evalMultKeyMap[key->GetKeyTag()] = GetScheme()->EvalMultKeysGen(key);
103	    }
