111	template <typename Element>
112	void CryptoContextImpl<Element>::ClearEvalMultKeys(const std::string& keyTag) {
113	    auto kd = CryptoContextImpl<Element>::s_evalMultKeyMap.find(keyTag);
114	    if (kd != CryptoContextImpl<Element>::s_evalMultKeyMap.end())
115	        CryptoContextImpl<Element>::s_evalMultKeyMap.erase(kd);
116	}
117	
118	template <typename Element>
119	void CryptoContextImpl<Element>::ClearEvalMultKeys(const CryptoContext<Element>& cc) {
120	    for (auto it = CryptoContextImpl<Element>::s_evalMultKeyMap.begin();
121	         it != CryptoContextImpl<Element>::s_evalMultKeyMap.end();) {
122	        if (it->second[0]->GetCryptoContext() == cc) {
123	            it = CryptoContextImpl<Element>::s_evalMultKeyMap.erase(it);
124	        }
125	        else {
126	            ++it;
127	        }
128	    }
129	}
