131	template <typename Element>
132	void CryptoContextImpl<Element>::InsertEvalMultKey(const std::vector<EvalKey<Element>>& vectorToInsert,
133	                                                   const std::string& keyTag) {
134	    const std::string& tag = (keyTag.empty()) ? vectorToInsert[0]->GetKeyTag() : keyTag;
135	    if (CryptoContextImpl<Element>::s_evalMultKeyMap.find(tag) != CryptoContextImpl<Element>::s_evalMultKeyMap.end()) {
136	        // we do not allow to override the existing key vector if its keyTag is identical to the keyTag of the new keys
137	        OPENFHE_THROW("Can not save a EvalMultKeys vector as there is a key vector for the given keyTag");
138	    }
139	    CryptoContextImpl<Element>::s_evalMultKeyMap[tag] = vectorToInsert;
140	}
