153	template <typename Element>
154	std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> CryptoContextImpl<Element>::EvalSumRowsKeyGen(
155	    const PrivateKey<Element> privateKey, uint32_t rowSize, uint32_t subringDim) {
156	    ValidateKey(privateKey);
