216	template <typename Element>
217	std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> CryptoContextImpl<Element>::GetPartialEvalAutomorphismKeyMapPtr(
218	    const std::string& keyTag, const std::vector<uint32_t>& indexList) {
219	    if (!indexList.size())
220	        OPENFHE_THROW("indexList is empty");
221	
222	    std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> keyMap =
223	        CryptoContextImpl<Element>::GetEvalAutomorphismKeyMapPtr(keyTag);
224	
225	    // create a return map if specific indices are provided
226	    std::map<uint32_t, EvalKey<Element>> retMap;
227	    for (uint32_t indx : indexList) {
228	        const auto it = keyMap->find(indx);
229	        if (it == keyMap->end()) {
230	            OPENFHE_THROW("Key is not generated for index [" + std::to_string(indx) + "] and keyTag [" + keyTag + "]");
231	        }
232	        retMap.emplace(indx, it->second);
233	    }
234	    return std::make_shared<std::map<uint32_t, EvalKey<Element>>>(retMap);
