312	template <typename Element>
313	std::set<uint32_t> CryptoContextImpl<Element>::GetExistingEvalAutomorphismKeyIndices(const std::string& keyTag) {
314	    auto keyMapIt = CryptoContextImpl<Element>::s_evalAutomorphismKeyMap.find(keyTag);
315	    if (keyMapIt == CryptoContextImpl<Element>::s_evalAutomorphismKeyMap.end())
316	        // there is no keys for the given keyTag, return empty vector
317	        return std::set<uint32_t>();
318	
319	    // get all inidices from the existing automorphism key map
320	    auto& keyMap = *(keyMapIt->second);
321	    std::set<uint32_t> indices;
322	    for (const auto& [key, _] : keyMap) {
323	        indices.insert(key);
324	    }
325	
326	    return indices;
327	}
