329	template <typename Element>
330	std::set<uint32_t> CryptoContextImpl<Element>::GetUniqueValues(const std::set<uint32_t>& oldValues,
331	                                                               const std::set<uint32_t>& newValues) {
332	    std::set<uint32_t> newUniqueValues;
333	    std::set_difference(newValues.begin(), newValues.end(), oldValues.begin(), oldValues.end(),
334	                        std::inserter(newUniqueValues, newUniqueValues.begin()));
335	    return newUniqueValues;
336	}
