338	template <typename Element>
339	void CryptoContextImpl<Element>::InsertEvalAutomorphismKey(
340	    const std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> mapToInsert, const std::string& keyTag) {
341	    // check if the map is empty
342	    if (mapToInsert->empty()) {
343	        return;
344	    }
345	
346	    auto mapToInsertIt    = mapToInsert->begin();
347	    const std::string& id = (keyTag.empty()) ? mapToInsertIt->second->GetKeyTag() : keyTag;
348	    std::set<uint32_t> existingIndices{CryptoContextImpl<Element>::GetExistingEvalAutomorphismKeyIndices(id)};
349	    if (existingIndices.empty()) {
350	        // there is no keys for the given id, so we insert full mapToInsert
351	        CryptoContextImpl<Element>::s_evalAutomorphismKeyMap[id] = mapToInsert;
352	    }
353	    else {
354	        // get all indices from mapToInsert
355	        std::set<uint32_t> newIndices;
356	        for (const auto& [key, _] : *mapToInsert) {
357	            newIndices.insert(key);
358	        }
359	
360	        // find all indices in mapToInsert that are not in the exising map and
361	        // insert those new indices and their corresponding keys to the existing map
362	        std::set<uint32_t> indicesToInsert{CryptoContextImpl<Element>::GetUniqueValues(existingIndices, newIndices)};
363	        auto keyMapIt = CryptoContextImpl<Element>::s_evalAutomorphismKeyMap.find(id);
364	        auto& keyMap  = *(keyMapIt->second);
365	        for (uint32_t indx : indicesToInsert) {
366	            keyMap[indx] = (*mapToInsert)[indx];
367	        }
368	    }
369	}
