448	template <typename Element>
449	DecryptResult CryptoContextImpl<Element>::Decrypt(ConstCiphertext<Element>& ciphertext,
450	                                                  const PrivateKey<Element>& privateKey, Plaintext* plaintext) {
451	    if (ciphertext == nullptr)
452	        OPENFHE_THROW("ciphertext is empty");
453	    if (plaintext == nullptr)
454	        OPENFHE_THROW("plaintext is empty");
455	    ValidateKey(privateKey);
456	
457	    // determine which type of plaintext that you need to decrypt into
458	    // Plaintext decrypted =
459	    // CryptoContextImpl<Element>::GetPlaintextForDecrypt(ciphertext->GetEncodingType(),
460	    // this->GetElementParams(), this->GetEncodingParams());
461	    Plaintext decrypted = CryptoContextImpl<Element>::GetPlaintextForDecrypt(
462	        ciphertext->GetEncodingType(), ciphertext->GetElements()[0].GetParams(), this->GetEncodingParams(),
463	        this->GetCKKSDataType());
464	
465	    DecryptResult result;
466	
467	    if ((ciphertext->GetEncodingType() == CKKS_PACKED_ENCODING) && (typeid(Element) != typeid(NativePoly))) {
468	        result = GetScheme()->Decrypt(ciphertext, privateKey, &decrypted->GetElement<Poly>());
469	    }
470	    else {
471	        result = GetScheme()->Decrypt(ciphertext, privateKey, &decrypted->GetElement<NativePoly>());
472	    }
473	
474	    if (result.isValid == false)  // TODO (dsuponit): why don't we throw an exception here?
475	        return result;
476	
477	    decrypted->SetScalingFactorInt(result.scalingFactorInt);
478	
479	    if (ciphertext->GetEncodingType() == CKKS_PACKED_ENCODING) {
480	        auto decryptedCKKS = std::dynamic_pointer_cast<CKKSPackedEncoding>(decrypted);
481	        decryptedCKKS->SetNoiseScaleDeg(ciphertext->GetNoiseScaleDeg());
482	        decryptedCKKS->SetLevel(ciphertext->GetLevel());
483	        decryptedCKKS->SetScalingFactor(ciphertext->GetScalingFactor());
484	        decryptedCKKS->SetSlots(ciphertext->GetSlots());
485	
486	        const auto cryptoParamsCKKS = std::dynamic_pointer_cast<CryptoParametersRNS>(this->GetCryptoParameters());
487	
488	        decryptedCKKS->Decode(ciphertext->GetNoiseScaleDeg(), ciphertext->GetScalingFactor(),
489	                              cryptoParamsCKKS->GetScalingTechnique(), cryptoParamsCKKS->GetExecutionMode());
490	    }
491	    else {
492	        decrypted->Decode();
493	    }
494	
495	    *plaintext = std::move(decrypted);
496	    return result;
497	}
