605	template <>
606	DecryptResult CryptoContextImpl<DCRTPoly>::MultipartyDecryptFusion(
607	    const std::vector<Ciphertext<DCRTPoly>>& partialCiphertextVec, Plaintext* plaintext) const {
608	    DecryptResult result;
609	
610	    // Make sure we're processing ciphertexts.
611	    size_t last_ciphertext = partialCiphertextVec.size();
612	    if (last_ciphertext < 1)
613	        return result;
614	
615	    for (size_t i = 0; i < last_ciphertext; i++) {
616	        ValidateCiphertext(partialCiphertextVec[i]);
617	        if (partialCiphertextVec[i]->GetEncodingType() != partialCiphertextVec[0]->GetEncodingType())
618	            OPENFHE_THROW("Ciphertexts have mismatched encoding types");
619	    }
620	
621	    // determine which type of plaintext that you need to decrypt into
622	    Plaintext decrypted = CryptoContextImpl<DCRTPoly>::GetPlaintextForDecrypt(
623	        partialCiphertextVec[0]->GetEncodingType(), partialCiphertextVec[0]->GetElements()[0].GetParams(),
624	        this->GetEncodingParams(), this->GetCKKSDataType());
625	
626	    if ((partialCiphertextVec[0]->GetEncodingType() == CKKS_PACKED_ENCODING) &&
627	        (partialCiphertextVec[0]->GetElements()[0].GetParams()->GetParams().size() > 1))
628	        result = GetScheme()->MultipartyDecryptFusion(partialCiphertextVec, &decrypted->GetElement<Poly>());
629	    else
630	        result = GetScheme()->MultipartyDecryptFusion(partialCiphertextVec, &decrypted->GetElement<NativePoly>());
631	
632	    if (result.isValid == false)
633	        return result;
634	
635	    decrypted->SetScalingFactorInt(result.scalingFactorInt);
636	
637	    if (partialCiphertextVec[0]->GetEncodingType() == CKKS_PACKED_ENCODING) {
638	        auto decryptedCKKS = std::dynamic_pointer_cast<CKKSPackedEncoding>(decrypted);
639	        decryptedCKKS->SetSlots(partialCiphertextVec[0]->GetSlots());
640	        const auto cryptoParamsCKKS = std::dynamic_pointer_cast<CryptoParametersCKKSRNS>(this->GetCryptoParameters());
641	        decryptedCKKS->Decode(partialCiphertextVec[0]->GetNoiseScaleDeg(), partialCiphertextVec[0]->GetScalingFactor(),
642	                              cryptoParamsCKKS->GetScalingTechnique(), cryptoParamsCKKS->GetExecutionMode());
643	    }
644	    else {
645	        decrypted->Decode();
646	    }
647	
648	    *plaintext = std::move(decrypted);
649	
650	    return result;
651	}
