697	// Function for sharing and recovery of secret for Threshold FHE with aborts
698	template <>
699	std::unordered_map<uint32_t, DCRTPoly> CryptoContextImpl<DCRTPoly>::ShareKeys(const PrivateKey<DCRTPoly>& sk,
700	                                                                              uint32_t N, uint32_t threshold,
701	                                                                              uint32_t index,
702	                                                                              const std::string& shareType) const {
703	    // conditions on N and threshold for security with aborts
704	    if (N < 2)
705	        OPENFHE_THROW("Number of parties needs to be at least 3 for aborts");
706	
707	    if (threshold <= N / 2)
708	        OPENFHE_THROW("Threshold required to be majority (more than N/2)");
709	
710	    const auto cryptoParams = sk->GetCryptoContext()->GetCryptoParameters();
711	    auto elementParams      = cryptoParams->GetElementParams();
712	    auto vecSize            = elementParams->GetParams().size();
713	    auto ring_dimension     = elementParams->GetRingDimension();
714	
715	    // condition for inverse in lagrange coeff to exist.
716	    for (size_t i = 0; i < vecSize; ++i) {
717	        auto modq_k = elementParams->GetParams()[i]->GetModulus();
718	        if (N >= modq_k)
719	            OPENFHE_THROW("Number of parties N needs to be less than DCRTPoly moduli");
720	    }
721	
722	    // secret sharing
723	    std::unordered_map<uint32_t, DCRTPoly> SecretShares;
724	
725	    if (shareType == "additive") {
726	        // generate a random share of N-2 elements and create the last share as sk - (sk_1 + ... + sk_N-2)
727	        typename DCRTPoly::DugType dug;
728	        DCRTPoly rsum(dug, elementParams, Format::EVALUATION);
729	
730	        const uint32_t num_of_shares = N - 1;
731	        std::vector<DCRTPoly> SecretSharesVec;
732	        SecretSharesVec.reserve(num_of_shares);
733	        SecretSharesVec.push_back(rsum);
734	        for (size_t i = 1; i < num_of_shares - 1; ++i) {
735	            DCRTPoly r(dug, elementParams, Format::EVALUATION);  // should re-generate uniform r for each share
736	            rsum += r;
737	            SecretSharesVec.push_back(std::move(r));
738	        }
739	        SecretSharesVec.push_back(sk->GetPrivateElement() - rsum);
740	
741	        for (size_t i = 1, ctr = 0; i <= N; ++i) {
742	            if (i != index) {
743	                SecretShares[i] = SecretSharesVec[ctr++];
744	            }
745	        }
746	    }
747	    else if (shareType == "shamir") {
748	        // vector to store columnwise randomly generated coefficients for polynomial f from Z_q for every secret key entry
749	        // set constant term of polynomial f_i to s_i
750	        std::vector<DCRTPoly> fs{sk->GetPrivateElement()};
751	        fs.back().SetFormat(Format::COEFFICIENT);
752	
753	        // generate random coefficients
754	        fs.reserve(threshold);
755	        typename DCRTPoly::DugType dug;
756	        for (size_t i = 1; i < threshold; ++i) {
757	            fs.emplace_back(dug, elementParams, Format::COEFFICIENT);
758	        }
759	
760	        // evaluate the polynomial at the index of the parties 1 to N
761	        for (size_t i = 1; i <= N; ++i) {
762	            if (i != index) {
763	                DCRTPoly feval(elementParams, Format::COEFFICIENT, true);
764	                for (size_t k = 0; k < vecSize; k++) {
765	                    auto modq_k = elementParams->GetParams()[k]->GetModulus();
766	
767	                    NativePoly powtemppoly(elementParams->GetParams()[k], Format::COEFFICIENT);
768	                    NativePoly fevalpoly(elementParams->GetParams()[k], Format::COEFFICIENT, true);
769	
770	                    NativeInteger powtemp(1);
771	                    for (size_t t = 1; t < threshold; t++) {
772	                        NativeVector powtempvec(ring_dimension, modq_k, (powtemp = powtemp.ModMul(i, modq_k)));
773	
774	                        powtemppoly.SetValues(std::move(powtempvec), Format::COEFFICIENT);
775	
776	                        auto& fst = fs[t].GetElementAtIndex(k);
777	
778	                        for (size_t i = 0; i < ring_dimension; ++i) {
779	                            fevalpoly[i] += powtemppoly[i].ModMul(fst[i], modq_k);
780	                        }
781	                    }
782	                    fevalpoly += fs[0].GetElementAtIndex(k);
783	
784	                    fevalpoly.SetFormat(Format::COEFFICIENT);
785	                    feval.SetElementAtIndex(k, std::move(fevalpoly));
786	                }
787	                // assign fi
788	                SecretShares.emplace(i, std::move(feval));
789	            }
790	        }
791	    }
792	    return SecretShares;
793	}
794	
795	template <>
796	void CryptoContextImpl<DCRTPoly>::RecoverSharedKey(PrivateKey<DCRTPoly>& sk,
797	                                                   std::unordered_map<uint32_t, DCRTPoly>& sk_shares, uint32_t N,
798	                                                   uint32_t threshold, const std::string& shareType) const {
799	    if (sk_shares.size() < threshold)
800	        OPENFHE_THROW("Number of shares available less than threshold of the sharing scheme");
801	
802	    // conditions on N and threshold for security with aborts
803	    if (N < 2)
804	        OPENFHE_THROW("Number of parties needs to be at least 3 for aborts");
805	
806	    if (threshold <= N / 2)
807	        OPENFHE_THROW("Threshold required to be majority (more than N/2)");
808	
809	    const auto& cryptoParams  = sk->GetCryptoContext()->GetCryptoParameters();
810	    const auto& elementParams = cryptoParams->GetElementParams();
811	    size_t ring_dimension     = elementParams->GetRingDimension();
812	    size_t vecSize            = elementParams->GetParams().size();
813	
814	    // condition for inverse in lagrange coeff to exist.
815	    for (size_t k = 0; k < vecSize; k++) {
816	        auto modq_k = elementParams->GetParams()[k]->GetModulus();
817	        if (N >= modq_k)
818	            OPENFHE_THROW("Number of parties N needs to be less than DCRTPoly moduli");
819	    }
820	
821	    // vector of indexes of the clients
822	    std::vector<uint32_t> client_indexes;
823	    client_indexes.reserve(N);
824	    for (uint32_t i = 1; i <= N; ++i) {
825	        if (sk_shares.find(i) != sk_shares.end())
826	            client_indexes.push_back(i);
827	    }
828	    const uint32_t client_indexes_size = client_indexes.size();
829	
830	    if (client_indexes_size < threshold)
831	        OPENFHE_THROW("Not enough shares to recover the secret");
832	
833	    if (shareType == "additive") {
834	        DCRTPoly sum_of_elems(elementParams, Format::EVALUATION, true);
835	        for (uint32_t i = 0; i < threshold; ++i) {
836	            sum_of_elems += sk_shares[client_indexes[i]];
837	        }
838	        sk->SetPrivateElement(std::move(sum_of_elems));
839	    }
840	    else if (shareType == "shamir") {
841	        // use lagrange interpolation to recover the secret
842	        // vector of lagrange coefficients L_j = Pdt_i ne j (i (i-j)^-1)
843	        std::vector<DCRTPoly> Lagrange_coeffs(client_indexes_size, DCRTPoly(elementParams, Format::EVALUATION));
844	
845	        // recovery of the secret with lagrange coefficients and the secret shares
846	        for (uint32_t j = 0; j < client_indexes_size; j++) {
847	            auto cj = client_indexes[j];
848	            for (size_t k = 0; k < vecSize; k++) {
849	                auto modq_k = elementParams->GetParams()[k]->GetModulus();
850	                NativePoly multpoly(elementParams->GetParams()[k], Format::COEFFICIENT, true);
851	                multpoly.AddILElementOne();
852	                for (uint32_t i = 0; i < client_indexes_size; i++) {
853	                    auto ci = client_indexes[i];
854	                    if (ci != cj) {
855	                        auto&& denominator = (cj < ci) ? NativeInteger(ci - cj) : modq_k - NativeInteger(cj - ci);
856	                        auto denom_inv{denominator.ModInverse(modq_k)};
857	                        for (size_t d = 0; d < ring_dimension; ++d)
858	                            multpoly[d].ModMulFastEq(NativeInteger(ci).ModMul(denom_inv, modq_k), modq_k);
859	                    }
860	                }
861	                multpoly.SetFormat(Format::EVALUATION);
862	                Lagrange_coeffs[j].SetElementAtIndex(k, std::move(multpoly));
863	            }
864	            Lagrange_coeffs[j].SetFormat(Format::COEFFICIENT);
865	        }
866	
867	        DCRTPoly lagrange_sum_of_elems(elementParams, Format::COEFFICIENT, true);
868	        for (size_t k = 0; k < vecSize; ++k) {
869	            NativePoly lagrange_sum_of_elems_poly(elementParams->GetParams()[k], Format::COEFFICIENT, true);
870	            for (uint32_t i = 0; i < client_indexes_size; ++i) {
871	                const auto& coeff = Lagrange_coeffs[i].GetAllElements()[k];
872	                const auto& share = sk_shares[client_indexes[i]].GetAllElements()[k];
873	                lagrange_sum_of_elems_poly += coeff.TimesNoCheck(share);
874	            }
875	            lagrange_sum_of_elems.SetElementAtIndex(k, std::move(lagrange_sum_of_elems_poly));
876	        }
877	        lagrange_sum_of_elems.SetFormat(Format::EVALUATION);
878	        sk->SetPrivateElement(std::move(lagrange_sum_of_elems));
879	    }
880	}
881	
882	// explicit template instantiations (including the instantiations reqiured for pybind11 binding)
883	// clang-format off
884	template class CryptoContextImpl<DCRTPoly>;
