135	template <class Element>
136	EvalKey<Element> LeveledSHEBase<Element>::EvalMultKeyGen(const PrivateKey<Element> privateKey) const {
137	    const auto cc = privateKey->GetCryptoContext();
138	    const auto& s = privateKey->GetPrivateElement();
139	
140	    auto privateKeySquared = std::make_shared<PrivateKeyImpl<Element>>(cc);
141	    privateKeySquared->SetPrivateElement(s * s);
142	
143	    return cc->GetScheme()->KeySwitchGen(privateKeySquared, privateKey);
144	}
145	
146	template <class Element>
147	std::vector<EvalKey<Element>> LeveledSHEBase<Element>::EvalMultKeysGen(const PrivateKey<Element> privateKey) const {
148	    const auto cc = privateKey->GetCryptoContext();
149	    const auto& s = privateKey->GetPrivateElement();
150	
151	    auto privateKeyPower = std::make_shared<PrivateKeyImpl<Element>>(cc);
152	    privateKeyPower->SetPrivateElement(s);
153	
154	    size_t maxRelinSkDeg = privateKey->GetCryptoParameters()->GetMaxRelinSkDeg() - 1;
155	    std::vector<EvalKey<Element>> evalKeyVec;
156	    evalKeyVec.reserve(maxRelinSkDeg);
157	    for (size_t i = 0; i < maxRelinSkDeg; ++i) {
158	        privateKeyPower->SetPrivateElement(s * privateKeyPower->GetPrivateElement());
159	        evalKeyVec.emplace_back(cc->GetScheme()->KeySwitchGen(privateKeyPower, privateKey));
160	    }
161	
162	    return evalKeyVec;
163	}
