181	template <class Element>
182	Ciphertext<Element> LeveledSHEBase<Element>::EvalMult(ConstCiphertext<Element>& ciphertext1,
183	                                                      ConstCiphertext<Element>& ciphertext2,
184	                                                      const EvalKey<Element> evalKey) const {
185	    auto ciphertext = EvalMult(ciphertext1, ciphertext2);
186	
187	    auto& cv = ciphertext->GetElements();
188	    for (auto& c : cv)
189	        c.SetFormat(Format::EVALUATION);
190	
191	    auto ab = ciphertext->GetCryptoContext()->GetScheme()->KeySwitchCore(cv[2], evalKey);
192	
193	    cv[0] += (*ab)[0];
194	    cv[1] += (*ab)[1];
195	
196	    cv.resize(2);
197	
198	    return ciphertext;
199	}
