326	template <class Element>
327	void LeveledSHEBase<Element>::RelinearizeInPlace(Ciphertext<Element>& ciphertext,
328	                                                 const std::vector<EvalKey<Element>>& evalKeyVec) const {
329	    auto& cv = ciphertext->GetElements();
330	    for (auto& c : cv)
331	        c.SetFormat(Format::EVALUATION);
332	
333	    auto algo = ciphertext->GetCryptoContext()->GetScheme();
334	
335	    for (size_t j = 2; j < cv.size(); ++j) {
336	        auto ab = algo->KeySwitchCore(cv[j], evalKeyVec[j - 2]);
337	        cv[0] += (*ab)[0];
338	        cv[1] += (*ab)[1];
339	    }
340	    cv.resize(2);
341	}
