345	/////////////////////////////////////////
346	
347	template <class Element>
348	std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> LeveledSHEBase<Element>::EvalAutomorphismKeyGen(
349	    const PrivateKey<Element> privateKey, const std::vector<uint32_t>& indexList) const {
350	    // Do not generate duplicate keys that have been already generated and added to the static storage (map)
351	    std::set<uint32_t> allIndices(indexList.begin(), indexList.end());
352	    std::set<uint32_t> indicesToGenerate{
353	        CryptoContextImpl<Element>::GetEvalAutomorphismNoKeyIndices(privateKey->GetKeyTag(), allIndices)};
354	    std::vector<uint32_t> newIndices(indicesToGenerate.begin(), indicesToGenerate.end());
355	
356	    // we already have checks on higher level?
357	    //  auto it = std::find(newIndices.begin(), newIndices.end(), 2 * n - 1);
358	    //  if (it != newIndices.end())
359	    //    OPENFHE_THROW("conjugation is disabled");
360	
361	    const auto cc = privateKey->GetCryptoContext();
362	    const auto& s = privateKey->GetPrivateElement();
363	
364	    const uint32_t N = s.GetRingDimension();
365	    const uint32_t M = s.GetCyclotomicOrder();
366	
367	    // we already have checks on higher level?
368	    //  if (newIndices.size() > N - 1)
369	    //    OPENFHE_THROW("size exceeds the ring dimension");
370	
371	    // create and initialize the key map (key is a value from newIndices, EvalKey is nullptr). in this case
372	    // we should be able to assign values to the map without using "omp critical" as all evalKeys' elements would
373	    // have already been created
374	    auto evalKeys = std::make_shared<std::map<uint32_t, EvalKey<Element>>>();
375	    for (auto indx : newIndices)
376	        (*evalKeys)[indx];
377	
378	    const uint32_t sz = newIndices.size();
379	#pragma omp parallel for
380	    for (uint32_t i = 0; i < sz; ++i) {
381	        auto index = NativeInteger(newIndices[i]).ModInverse(M).ConvertToInt<uint32_t>();
382	        std::vector<uint32_t> vec(N);
383	        PrecomputeAutoMap(N, index, &vec);
384	
385	        auto privateKeyPermuted = std::make_shared<PrivateKeyImpl<Element>>(cc);
386	        privateKeyPermuted->SetPrivateElement(s.AutomorphismTransform(index, vec));
387	        (*evalKeys)[newIndices[i]] = cc->GetScheme()->KeySwitchGen(privateKey, privateKeyPermuted);
388	    }
389	
390	    return evalKeys;
391	}
392	
393	template <class Element>
394	Ciphertext<Element> LeveledSHEBase<Element>::EvalAutomorphism(ConstCiphertext<Element>& ciphertext, uint32_t i,
395	                                                              const std::map<uint32_t, EvalKey<Element>>& evalKeyMap,
396	                                                              CALLER_INFO_ARGS_CPP) const {
397	    // this operation can be performed on 2-element ciphertexts only
398	    if (ciphertext->NumberCiphertextElements() != 2)
399	        OPENFHE_THROW("Ciphertext should be relinearized before.");
400	
401	    // verify if the key i exists in the evalKeyMap
402	    auto evalKeyIterator = evalKeyMap.find(i);
403	    if (evalKeyIterator == evalKeyMap.end())
404	        OPENFHE_THROW("EvalKey for index [" + std::to_string(i) + "] is not found." + CALLER_INFO);
405	
406	    // we already have checks on higher level?
407	    //  if (cv.size() < 2) {
408	    //    std::string errorMsg(
409	    //        std::string("Insufficient number of elements in ciphertext: ") +
410	    //        std::to_string(cv.size()) + CALLER_INFO);
411	    //    OPENFHE_THROW( errorMsg);
412	    //  }
413	
414	    uint32_t N = ciphertext->GetElements()[0].GetRingDimension();
415	
416	    //  if (i == 2 * N - 1)
417	    //    OPENFHE_THROW(
418	    //                   "conjugation is disabled " + CALLER_INFO);
419	
420	    //  if (i > 2 * N - 1)
421	    //    OPENFHE_THROW(
422	    //        "automorphism indices higher than 2*n are not allowed " + CALLER_INFO);
423	
424	    auto result = ciphertext->Clone();
425	    ciphertext->GetCryptoContext()->GetScheme()->KeySwitchInPlace(result, evalKeyIterator->second);
426	
427	    std::vector<uint32_t> vec(N);
428	    PrecomputeAutoMap(N, i, &vec);
429	
430	    auto& rcv = result->GetElements();
431	    rcv[0]    = rcv[0].AutomorphismTransform(i, vec);
432	    rcv[1]    = rcv[1].AutomorphismTransform(i, vec);
433	    return result;
434	}
