444	template <class Element>
445	Ciphertext<Element> LeveledSHEBase<Element>::EvalFastRotation(
446	    ConstCiphertext<Element>& ciphertext, const uint32_t index, const uint32_t m,
447	    const std::shared_ptr<std::vector<Element>> digits) const {
448	    if (index == 0)
449	        return ciphertext->Clone();
450	
451	    uint32_t autoIndex   = FindAutomorphismIndex(index, m);
452	    const auto cc        = ciphertext->GetCryptoContext();
453	    auto evalKeyMap      = cc->GetEvalAutomorphismKeyMap(ciphertext->GetKeyTag());
454	    auto evalKeyIterator = evalKeyMap.find(autoIndex);
455	    if (evalKeyIterator == evalKeyMap.end())
456	        OPENFHE_THROW("EvalKey for index [" + std::to_string(autoIndex) + "] is not found.");
457	    auto evalKey = evalKeyIterator->second;
458	
459	    const auto cryptoParams = ciphertext->GetCryptoParameters();
460	
461	    const uint32_t N = cryptoParams->GetElementParams()->GetRingDimension();
462	    std::vector<uint32_t> vec(N);
463	    PrecomputeAutoMap(N, autoIndex, &vec);
464	
465	    const auto& cv = ciphertext->GetElements();
466	
467	    auto ba = *cc->GetScheme()->EvalFastKeySwitchCore(digits, evalKey, cv[0].GetParams());
468	    ba[0] += cv[0];
469	    ba[0] = ba[0].AutomorphismTransform(autoIndex, vec);
470	    ba[1] = ba[1].AutomorphismTransform(autoIndex, vec);
471	
472	    auto result = ciphertext->CloneEmpty();
473	    result->SetElements(std::move(ba));
474	    return result;
475	}
