477	template <class Element>
478	std::shared_ptr<std::map<uint32_t, EvalKey<Element>>> LeveledSHEBase<Element>::EvalAtIndexKeyGen(
479	    const PrivateKey<Element> privateKey, const std::vector<int32_t>& indexList) const {
480	    uint32_t M = privateKey->GetCryptoParameters()->GetElementParams()->GetCyclotomicOrder();
481	    std::vector<uint32_t> autoIndices(indexList.size());
482	    for (size_t i = 0; i < indexList.size(); i++)
483	        autoIndices[i] = FindAutomorphismIndex(indexList[i], M);
484	    return EvalAutomorphismKeyGen(privateKey, autoIndices);
485	}
