487	template <class Element>
488	Ciphertext<Element> LeveledSHEBase<Element>::EvalAtIndex(ConstCiphertext<Element>& ciphertext, int32_t index,
489	                                                         const std::map<uint32_t, EvalKey<Element>>& evalKeyMap) const {
490	    uint32_t M = ciphertext->GetCryptoParameters()->GetElementParams()->GetCyclotomicOrder();
491	    return EvalAutomorphism(ciphertext, FindAutomorphismIndex(index, M), evalKeyMap);
