523	    auto elem = plaintext->GetElement<Element>();
524	    elem.SetFormat(EVALUATION);
525	
526	    auto result = ciphertext->CloneEmpty();
527	    result->SetElement(std::move(elem));
528	    result->SetSlots(plaintext->GetSlots());
529	    result->SetLevel(plaintext->GetLevel());
530	    result->SetNoiseScaleDeg(plaintext->GetNoiseScaleDeg());
