540	template <class Element>
541	void LeveledSHEBase<Element>::VerifyNumOfTowers(ConstCiphertext<Element>& ciphertext1,
542	                                                ConstCiphertext<Element>& ciphertext2, CALLER_INFO_ARGS_CPP) const {
543	    uint32_t numTowers1 = ciphertext1->GetElements()[0].GetNumOfElements();
544	    uint32_t numTowers2 = ciphertext2->GetElements()[0].GetNumOfElements();
545	    if (numTowers1 != numTowers2) {
546	        std::string errorMsg(std::string("Number of towers is not the same for ciphertext1 [") +
547	                             std::to_string(numTowers1) + "] and for ciphertext2 [" + std::to_string(numTowers2) +
548	                             "] " + CALLER_INFO);
549	        OPENFHE_THROW(errorMsg);
550	    }
551	}
552	template <class Element>
553	void LeveledSHEBase<Element>::VerifyNumOfTowers(ConstCiphertext<Element>& ciphertext, const Element& plaintext,
554	                                                CALLER_INFO_ARGS_CPP) const {
555	    uint32_t numTowersCtxt = ciphertext->GetElements()[0].GetNumOfElements();
556	    uint32_t numTowersPtxt = plaintext.GetNumOfElements();
557	    if (numTowersCtxt != numTowersPtxt) {
558	        std::string errorMsg(std::string("Number of towers is not the same for ciphertext[") +
559	                             std::to_string(numTowersCtxt) + "] and for plaintext[" + std::to_string(numTowersPtxt) +
560	                             "]" + CALLER_INFO);
561	        OPENFHE_THROW(errorMsg);
562	    }
563	}
