573	template <class Element>
574	void LeveledSHEBase<Element>::EvalAddCoreInPlace(Ciphertext<Element>& ciphertext1,
575	                                                 ConstCiphertext<Element>& ciphertext2) const {
576	    VerifyNumOfTowers(ciphertext1, ciphertext2);
577	    auto& cv1 = ciphertext1->GetElements();
578	    auto& cv2 = ciphertext2->GetElements();
579	
580	    uint32_t c1Size     = cv1.size();
581	    uint32_t c2Size     = cv2.size();
582	    uint32_t cSmallSize = std::min(c1Size, c2Size);
583	
584	    cv1.reserve(c2Size);
585	    uint32_t i = 0;
586	    for (; i < cSmallSize; ++i)
587	        cv1[i] += cv2[i];
588	    for (; i < c2Size; ++i)
589	        cv1.emplace_back(cv2[i]);
590	}
591	
592	template <class Element>
593	Ciphertext<Element> LeveledSHEBase<Element>::EvalSubCore(ConstCiphertext<Element>& ciphertext1,
594	                                                         ConstCiphertext<Element>& ciphertext2) const {
595	    auto result = ciphertext1->Clone();
596	    EvalSubCoreInPlace(result, ciphertext2);
597	    return result;
598	}
