600	template <class Element>
601	void LeveledSHEBase<Element>::EvalSubCoreInPlace(Ciphertext<Element>& ciphertext1,
602	                                                 ConstCiphertext<Element>& ciphertext2) const {
603	    VerifyNumOfTowers(ciphertext1, ciphertext2);
604	    auto& cv1 = ciphertext1->GetElements();
605	    auto& cv2 = ciphertext2->GetElements();
606	
607	    uint32_t c1Size     = cv1.size();
608	    uint32_t c2Size     = cv2.size();
609	    uint32_t cSmallSize = std::min(c1Size, c2Size);
610	
611	    cv1.reserve(c2Size);
612	    uint32_t i = 0;
613	    for (; i < cSmallSize; ++i)
614	        cv1[i] -= cv2[i];
615	    for (; i < c2Size; ++i)
616	        cv1.emplace_back(cv2[i].Negate());
617	}
618	
619	template <class Element>
620	Ciphertext<Element> LeveledSHEBase<Element>::EvalMultCore(ConstCiphertext<Element>& ctxt1,
621	                                                          ConstCiphertext<Element>& ctxt2) const {
622	    VerifyNumOfTowers(ctxt1, ctxt2);
623	    auto& cv1 = ctxt1->GetElements();
624	    auto& cv2 = ctxt2->GetElements();
625	
626	    uint32_t n1 = cv1.size();
627	    uint32_t n2 = cv2.size();
628	    uint32_t nr = n1 + n2 - 1;
629	
630	    std::vector<DCRTPoly> cvr;
631	    cvr.reserve(nr);
632	    if (n1 == 2 && n2 == 2) {
633	        cvr.emplace_back(cv1[0] * cv2[0]);
634	        cvr.emplace_back((cv1[0] * cv2[1]) += (cv1[1] * cv2[0]));
635	        cvr.emplace_back(cv1[1] * cv2[1]);
636	    }
637	    else {
638	        uint32_t m = 0;
639	        for (uint32_t i = 0; i < n1; ++i) {
640	            auto& cv1i = cv1[i];
641	            for (uint32_t j = 0, k = i; j < n2; ++j, ++k) {
642	                if (k == m) {
643	                    cvr.emplace_back(cv1i * cv2[j]);
644	                    ++m;
645	                }
646	                else {
647	                    cvr[k] += (cv1i * cv2[j]);
648	                }
649	            }
650	        }
651	    }
652	
653	    auto result = ctxt1->CloneEmpty();
654	    result->SetElements(std::move(cvr));
655	    result->SetNoiseScaleDeg(ctxt1->GetNoiseScaleDeg() + ctxt2->GetNoiseScaleDeg());
656	    result->SetScalingFactor(ctxt1->GetScalingFactor() * ctxt2->GetScalingFactor());
657	    result->SetScalingFactorInt(ctxt1->GetScalingFactorInt().ModMul(
658	        ctxt2->GetScalingFactorInt(), ctxt1->GetCryptoParameters()->GetPlaintextModulus()));
659	    return result;
660	}
661	
662	template <class Element>
663	Ciphertext<Element> LeveledSHEBase<Element>::EvalSquareCore(ConstCiphertext<Element>& ctxt) const {
664	    const auto& cv = ctxt->GetElements();
665	
666	    uint32_t n  = cv.size();
667	    uint32_t nr = (n << 1) - 1;
668	
669	    std::vector<DCRTPoly> cvr;
670	    cvr.reserve(nr);
671	    if (n == 2) {
672	        cvr.emplace_back(cv[0] * cv[0]);
673	        cvr.emplace_back(cv[0] * cv[1]);
674	        cvr.back() += cvr.back();
675	        cvr.emplace_back(cv[1] * cv[1]);
676	    }
677	    else {
678	        DCRTPoly cvt;
679	        uint32_t m = 0;
680	        for (uint32_t i = 0; i < n; ++i) {
681	            auto& cvi = cv[i];
682	            for (uint32_t j = i, k = 2 * i; j < n; ++j, ++k) {
683	                if (j == i) {
684	                    if (k == m) {
685	                        cvr.emplace_back(cvi * cvi);
686	                        ++m;
687	                    }
688	                    else {
689	                        cvr[k] += (cvi * cvi);
690	                    }
691	                }
692	                else {
693	                    if (k == m) {
694	                        cvr.emplace_back(cvi * cv[j]);
695	                        cvr.back() += cvr.back();
696	                        ++m;
697	                    }
698	                    else {
699	                        cvt = (cvi * cv[j]);
700	                        cvr[k] += (cvt += cvt);
701	                    }
702	                }
703	            }
704	        }
705	    }
706	
707	    auto result = ctxt->CloneEmpty();
708	    result->SetElements(std::move(cvr));
709	    result->SetNoiseScaleDeg(2 * ctxt->GetNoiseScaleDeg());
710	    result->SetScalingFactor(ctxt->GetScalingFactor() * ctxt->GetScalingFactor());
711	    result->SetScalingFactorInt(ctxt->GetScalingFactorInt().ModMul(ctxt->GetScalingFactorInt(),
712	                                                                   ctxt->GetCryptoParameters()->GetPlaintextModulus()));
713	    return result;
714	}
715	
716	template <class Element>
717	Ciphertext<Element> LeveledSHEBase<Element>::EvalAddCore(ConstCiphertext<Element>& ciphertext,
718	                                                         const Element& pt) const {
719	    auto result = ciphertext->Clone();
720	    EvalAddCoreInPlace(result, pt);
721	    return result;
722	}
