738	template <class Element>
739	void LeveledSHEBase<Element>::EvalSubCoreInPlace(Ciphertext<Element>& ciphertext, const Element& pt) const {
740	    VerifyNumOfTowers(ciphertext, pt);
741	    ciphertext->GetElements()[0] -= pt;
742	}
