1974	    Ciphertext<Element> EvalMultNoRelinNoCheck(ConstCiphertext<Element>& ctxt1, ConstCiphertext<Element>& ctxt2) const {
1975	        auto& cv1 = ctxt1->GetElements();
1976	        auto& cv2 = ctxt2->GetElements();
1977	
1978	        uint32_t n1 = cv1.size();
1979	        uint32_t n2 = cv2.size();
1980	        uint32_t nr = n1 + n2 - 1;
1981	
1982	        std::vector<DCRTPoly> cvr;
1983	        cvr.reserve(nr);
1984	
1985	        if (n1 == 2 && n2 == 2) {
1986	            cvr.emplace_back(cv1[0] * cv2[0]);
1987	            cvr.emplace_back((cv1[0] * cv2[1]) += (cv1[1] * cv2[0]));
1988	            cvr.emplace_back(cv1[1] * cv2[1]);
1989	        }
1990	        else {
1991	            uint32_t m = 0;
1992	            for (uint32_t i = 0; i < n1; ++i) {
1993	                auto& cv1i = cv1[i];
1994	                for (uint32_t j = 0, k = i; j < n2; ++j, ++k) {
1995	                    if (k == m) {
1996	                        cvr.emplace_back(cv1i * cv2[j]);
1997	                        ++m;
1998	                    }
1999	                    else {
2000	                        cvr[k] += (cv1i * cv2[j]);
2001	                    }
2002	                }
2003	            }
2004	        }
2005	
2006	        auto result = ctxt1->CloneEmpty();
2007	        result->SetElements(std::move(cvr));
2008	        result->SetNoiseScaleDeg(ctxt1->GetNoiseScaleDeg() + ctxt2->GetNoiseScaleDeg());
2009	        result->SetScalingFactor(ctxt1->GetScalingFactor() * ctxt2->GetScalingFactor());
2010	        result->SetScalingFactorInt(ctxt1->GetScalingFactorInt().ModMul(
2011	            ctxt2->GetScalingFactorInt(), ctxt1->GetCryptoParameters()->GetPlaintextModulus()));
2012	        return result;
